import { createContext } from '@src/framework/runtime-context';
import {
  FormItemValue,
  FormListField,
  FormListValue,
  GeneralFormValue,
  ValidationStates,
  WatchCallBack,
} from './types';
import type { KsFormItem } from '@src/components/ks-form-item';
import type { KsFormList } from '@src/components/ks-form-list';
import { Status } from '@src/shared/base-props';

export interface FormListUtils {
  /** Add a new item to the form list. */
  add: (defaultValue?: GeneralFormValue, index?: number) => void;
  /** Remove items from the form list. */
  remove: (index: number | number[]) => void;
  /** Move items in the form list. */
  move: (from: number, to: number) => void;
  /** Map the value of the form list to the fields of the form. */
  _mapValueToFields: (value: FormListValue) => FormListField[];
}

export interface FormContextValue<
  T extends GeneralFormValue = GeneralFormValue,
  E extends KsFormItem | KsFormList = KsFormItem | KsFormList,
> {
  _provider?: E extends KsFormItem ? 'formItem' : E extends KsFormList ? 'formList' : 'form';
  /** The prefix path of the form. */
  _prefixPath: string[];
  /** Whether the form is disabled. */
  disabled?: boolean;
  /** The validation status of the form. */
  status?: Status;
  /** The width px of the label in the form. */
  labelWidth?: number;
  /** The label alignment of the form. */
  labelAlign?: 'left' | 'right';
  /** The value of the form. */
  value: T;
  /** The validation status of the form. */
  validationStates: ValidationStates;
  /** callback functions for child components. */
  callbacks: {
    /** The callback function that is called when the form value changes. */
    onValueChange: (value: T, path: string[], originalPath?: string[]) => void;
    /** The callback function that is called when the form child blur. */
    onBlur: (originalPath?: string[]) => void;
    /** The callback function that is called when the form is validated. */
    onValidation: (path?: string[]) => Promise<void>;
    /** The callback function that is called when the validation status of the form changes. */
    _onValidationStatesChange: (validationStates: ValidationStates, path?: string[]) => void;
    /** Reset the validation status of the form. */
    onResetValidation: (path?: string[]) => void;
    /** The callback function that is called when the child component is connected. */
    _onComponentConnect: (instance: E, path?: string[]) => void;
    /** The callback function that is called when the child component is disconnected. */
    _onComponentDisconnect: (instance: E, path?: string[]) => void;
    /** The callback function that is called when the path of the child component changes. */
    _onPathChange: (instance: E, pathFrom: string[], pathTo: string[]) => void;
    /** The callback function that is called when the child component is unsubscribed. */
    _onComponentUnsubscribe?: () => void;
    /** Register watch callback. */
    _registerWatch: (path: string[] | string, callback: WatchCallBack, shouldCallImmediately?: boolean) => () => void;
    /** Unsubscribe context. */
    _unsubscribeContext?: T extends FormItemValue ? () => void : never;
  };
  /** Utilities for form list operations. */
  listUtils?: T extends FormListValue ? FormListUtils : never;
}

export const FormContext = createContext<FormContextValue>('form-context');
